def on_forever():
    if mySprite.vx > 100:
        mySprite.vx = 100
    if mySprite.is_hitting_tile(CollisionDirection.BOTTOM) and controller.A.is_pressed():
        mySprite.ay = -500
        mySprite.vy = -100
        pause(40)
        
        def on_background2():
            for index2 in range(36):
                if mySprite.is_hitting_tile(CollisionDirection.BOTTOM):
                    transformSprites.rotate_sprite(mySprite,
                        Math.round(transformSprites.get_rotation(mySprite) / 90) * 90)
                else:
                    transformSprites.change_rotation(mySprite, 5)
                    pause(1)
        timer.background(on_background2)
        
        pause(100)
        mySprite.ay = 500
    if mySprite.is_hitting_tile(CollisionDirection.RIGHT):
        gameOver()
forever(on_forever)
